        {"t": "h2", "x": "4. Field value quick reference"},
        {"t": "defs", "h": ["Value", "Meaning"], "items": [
             ["Material type ROH / HALB / FERT", "Raw material / semi-finished / finished good; decides which views are available and the default accounts"],
             ["Price control S / V", "Standard price / moving average; with S the difference goes to a price variance account, with V the unit price is recalculated on every receipt"],
             ["MRP type PD / ND / VB", "Demand-driven planning / not planned / manual reorder point"],
             ["Lot size EX / FX / HB", "Exactly the net requirement / fixed lot size / top up to maximum"],
             ["Movement type 101 / 122 / 501 / 561", "Goods receipt against order / return to vendor / receipt without PO / initial stock load"],
             ["Movement type 311 / 301 / 261 / 201", "Storage location transfer / plant transfer / production issue / cost center issue"],
             ["Document type NB / FO / UB", "Standard order / framework order / stock transport order"],
             ["Tolerance keys BD / DQ / PP / VP", "Small difference / quantity deviation / price change / moving average variance"],
             ["Payment terms 0001", "Immediate payment (used here); real systems commonly use 0002 = 14 days 2% discount or Z030 = 30 days net"],
             ["Valuation class 3000", "Raw materials; maps to inventory account 140000 in OBYC"],
         ]},

